class Singleton:
    # 유일한 인스턴스를 저장할 클래스 변수
    _instance = None
    def __new__(cls, *args, **kwargs):
        if cls._instance is None:
            # 인스턴스가 생성된 적이 없다면 새로 생성
            cls._instance = super().__new__(cls)
            print("create instance=======")
        print("__new__", args, kwargs)
        return cls._instance

