def get_section_numbers(numbers: List[int], section: int) -> List[int]:
    """
    [기능 4] 로또 번호를 5구간 또는 9구간으로 나누어
    특정 구간에 속하는 번호들을 리스트로 반환합니다.
    """
    counts = [0] * 9  # 9구간 카운터 초기화
    if section not in [5, 9]:
        raise ValueError("구간은 5 또는 9만 가능합니다.")
    for num in numbers:
        counts[(num - 1) // section] += 1

class Dic:
    def __init__(self):
        self.mydic = defaultdict(int)
    def toString(self) -> str:
        # 1. 각 키와 값을 문자열 라인으로 포맷팅하여 리스트로 생성
        lines = [f"{key}\t{Str.number_format(value)}" for key, value in self.mydic.items()]
        # 2. 줄바꿈 문자로 연결하여 하나의 문자열로 반환
        return "\n".join(lines)
    # key: true이면 key로 정렬, false이면 value로 정렬
